sp_widget.client_script:
api.controller = function ($sce, $window) {
  var c = this;
  function sget(k, d) { try { return $window.localStorage.getItem(k) || d; } catch (e) { return d; } }
  c.ar = sget('vroLang', 'ar') === 'ar';
  c.dark = sget('vroTheme', 'light') === 'dark';
  c.lab = function (l) { return l ? ((c.ar ? l.ar : l.en) || l.en || '') : ''; };
  c.num = function (n) { return c.ar ? String(n).replace(/[0-9]/g, function (d) { return '٠١٢٣٤٥٦٧٨٩'.charAt(d); }) : String(n); };
  var P = {
    home: 'M3 11l9-8 9 8M5 10v10h5v-6h4v6h5V10', flag: 'M5 21V4M5 4h11l-2 4 2 4H5', layers: 'M12 3l9 5-9 5-9-5 9-5zM3 13l9 5 9-5',
    target: 'M12 21a9 9 0 100-18 9 9 0 000 18zM12 16a4 4 0 100-8 4 4 0 000 8zM12 12h.01', bulb: 'M9 18h6M10 21h4M12 3a6 6 0 00-4 10.5c.7.7 1 1.5 1 2.5h6c0-1 .3-1.8 1-2.5A6 6 0 0012 3z',
    folder: 'M3 6a2 2 0 012-2h4l2 2h8a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V6z', org: 'M12 3v5M5 21v-5a2 2 0 012-2h10a2 2 0 012 2v5M12 8a2 2 0 100 4 2 2 0 000-4z',
    list: 'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01', tag: 'M20 12l-8 8-9-9V4h7l10 8zM7.5 8.5h.01', dot: 'M12 12h.01'
  };
  c.icon = function (n) { return $sce.trustAsHtml('<svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="' + (P[n] || P.dot) + '"/></svg>'); };
  c.big = function (key) { var r = 0; (c.data.cards || []).forEach(function (x) { if (x.key === key) { r = x.count; } }); return r; };
};

sp_widget.css:
.vro-home { --card: #ffffff; --head: #003462; --soft: #E6F2EC; --text: #17304a; --muted: #64788a; --line: #e2eae6;
  max-width: 1320px; margin: 0 auto; padding: 18px 16px 60px; font-family: 'Segoe UI', Tahoma, Arial, sans-serif; color: var(--text); display: grid; gap: 18px;
  > * { min-width: 0; }
  .vh-hero { background: linear-gradient(120deg, #003462 0%, #0d5c7a 52%, #1B8354 100%); color: #fff; border-radius: 26px; padding: 28px 30px; display: grid; grid-template-columns: 1.2fr 1fr; gap: 22px; align-items: center; position: relative; overflow: hidden; }
  .vh-hero:before, .vh-hero:after { content: ""; position: absolute; border-radius: 50%; background: rgba(255,255,255,.07); }
  .vh-hero:before { width: 280px; height: 280px; inset-inline-end: -70px; top: -90px; }
  .vh-hero:after { width: 180px; height: 180px; inset-inline-start: 30%; bottom: -100px; }
  .vh-hero > * { position: relative; z-index: 1; }
  .vh-hero h1 { margin: 0 0 6px; font-size: 2em; color: #fff; }
  .vh-hero p { margin: 0 0 16px; color: #d4e6ef; }
  .vh-cta { display: flex; gap: 10px; flex-wrap: wrap; }
  .vh-b { display: inline-flex; align-items: center; height: 44px; padding: 0 22px; border-radius: 99px; font-weight: 800; text-decoration: none; }
  .vh-b.w { background: #fff; color: #003462; }
  .vh-b.g { background: rgba(255,255,255,.16); color: #fff; border: 1.5px solid rgba(255,255,255,.4); }
  .vh-b:hover { text-decoration: none; opacity: .92; }
  .vh-big { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
  .vh-big > div { background: rgba(255,255,255,.12); border-radius: 18px; padding: 16px; text-align: center; }
  .vh-big b { display: block; font-size: 2.2em; line-height: 1.1; color: #fff; }
  .vh-big span { color: #d4e6ef; font-size: .9em; }
  .vh-h { margin: 6px 0 0; font-size: 1.25em; color: var(--head); }
  .vh-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 16px; }
  .vh-card { display: flex; align-items: center; gap: 14px; background: var(--card); border: 1px solid var(--line); border-radius: 20px; box-shadow: 0 10px 30px rgba(0,52,98,.08); padding: 18px; text-decoration: none; color: var(--text); transition: transform .15s; }
  .vh-card:hover { border-color: #1B8354; text-decoration: none; transform: translateY(-2px); }
  .vh-ico { flex: none; width: 54px; height: 54px; border-radius: 16px; display: inline-flex; align-items: center; justify-content: center; background: #E6F2EC; color: #1B8354; }
  .vh-ico.c2 { background: #e5eef9; color: #2f7fc1; }
  .vh-ico.c3 { background: #fdf0dd; color: #c97800; }
  .vh-ico.c4 { background: #f1e8f7; color: #7b4aa0; }
  .vh-ico.c5 { background: #fbe8e5; color: #C0392B; }
  .vh-tx { display: grid; line-height: 1.2; }
  .vh-tx b { font-size: 1.9em; color: var(--head); }
  .vh-tx span { color: var(--muted); }
  .vh-panel { background: var(--card); border: 1px solid var(--line); border-radius: 20px; padding: 20px; }
  .vh-panel h3 { margin: 0 0 6px; color: var(--head); }
  .vh-note, .vh-meta { color: var(--muted); margin: 0 0 12px; }
  .vh-links { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 12px; }
  .vh-links a { background: #E6F2EC; color: #12804e; border-radius: 99px; padding: 8px 16px; font-weight: 700; text-decoration: none; }
}
.vro-home.dark { --card: #152636; --head: #E8F1F8; --text: #dbe7f1; --muted: #8fa6ba; --line: #26425b; background: #0B1824; border-radius: 20px; }
@media (max-width: 860px) { .vro-home .vh-hero { grid-template-columns: 1fr; padding: 20px; } }

