  var scope = gs.getCurrentScopeName();
  data.name = String(gs.getUserDisplayName() || '');
  data.cards = [];
  UI.pages.forEach(function (p) {
    if (p.widget !== 'vro_table' || !p.options) { return; }
    var tn = p.options.table, ga = new GlideAggregate(scope + '_' + tn);
    ga.addAggregate('COUNT'); ga.query();
    var n = ga.next() ? parseInt(ga.getAggregate('COUNT'), 10) : 0;
    var mi = null;
    ((UI.menu && UI.menu.items) || []).forEach(function (m) { if (m.page === p.id) { mi = m; } });
    data.cards.push({ page: p.id, title: UI.tables[tn].title, count: n, icon: mi ? (mi.icon || 'dot') : 'dot', color: mi ? (mi.color || 'c1') : 'c1', key: tn });
